if (c.z > 0.5) { return y <= b.z + c.x && abs(ds) <= outerHW; }
if (y <= b.z) { return abs(ds) <= outerHW; }
let outerRise = b.w + c.x;
if (y > b.z + outerRise || outerRise <= 0.0) { return false; }
let ex = ds / max(outerHW, 0.001);
let ey = (y - b.z) / max(outerRise, 0.001);
